// Validate required payload fields
const body = $input.first().json.body || $input.first().json;

const required = [
  'sessionId',
  'studyUnitId',
  'certificationProgram',
  'phase',
  'userMessage',
  'intent',
  'timestamp'
];

const missing = required.filter(field => !body[field]);

if (missing.length > 0) {
  return [{
    json: {
      valid: false,
      error: 'Invalid payload',
      missing: missing
    }
  }];
}

// Validate certificationProgram is one of the allowed values
const allowedPrograms = ['CIA', 'CMA', 'CFE', 'CPA'];
if (!allowedPrograms.includes(body.certificationProgram)) {
  return [{
    json: {
      valid: false,
      error: 'Invalid payload',
      missing: [],
      details: `certificationProgram must be one of: ${allowedPrograms.join(', ')}`
    }
  }];
}

return [{
  json: {
    valid: true,
    sessionId: body.sessionId,
    studyUnitId: body.studyUnitId,
    certificationProgram: body.certificationProgram,
    phase: body.phase,
    userMessage: body.userMessage,
    intent: body.intent,
    timestamp: body.timestamp
  }
}];

