// Phase Router Tool
// Input: { currentPhase, userMessage, intent }
// Returns: { allowedActions, nextStepLabel, phaseGateRequired, errorIfSkip }

const PHASE_ORDER = ['INITIATION', 'TEXTBOOK', 'MCQ', 'SLIDES', 'SCRIPT', 'FLASHCARDS', 'CLOSEOUT'];

const PHASE_CONFIG = {
  INITIATION: {
    allowed: [
      'USER_CONFIRMATION_YES',
      'USER_CONFIRMATION_NO',
      'PHASE_TRANSITION_REQUEST'
    ],
    nextStep: 'TEXTBOOK',
    description: 'Confirm source materials are ready before proceeding'
  },
  TEXTBOOK: {
    allowed: [
      'PROMPT_TEXTBOOK_SECTION',
      'PROMPT_EXPAND',
      'PROMPT_CONDENSE',
      'PROMPT_REWRITE',
      'PROMPT_INSERT_CONTENT',
      'PROMPT_FORMAT_ONLY',
      'PROMPT_FALLBACK_REVISION',
      'USER_CONFIRMATION_YES',
      'USER_CONFIRMATION_NO',
      'PHASE_TRANSITION_REQUEST'
    ],
    nextStep: 'MCQ',
    description: 'Textbook creation, revision, Dropbox upload, Monday update'
  },
  MCQ: {
