    ],
    nextStep: 'CLOSEOUT',
    description: 'Flashcard generation, Dropbox upload'
  },
  CLOSEOUT: {
    allowed: [
      'PROCESS_CLOSEOUT',
      'USER_CONFIRMATION_YES',
      'USER_CONFIRMATION_NO'
    ],
    nextStep: null,
    description: 'Close out process, finalize Monday task status to Complete'
  }
};

// Parse input
let input;
try {
  input = typeof $input.first().json === 'string'
    ? JSON.parse($input.first().json)
    : $input.first().json;
} catch (e) {
  return [{ json: { error: 'Invalid JSON input to phase_router' } }];
}

const { currentPhase, intent } = input;
const phaseKey = (currentPhase || 'INITIATION').toUpperCase().replace(/\s+/g, '_');
const phaseConfig = PHASE_CONFIG[phaseKey];

if (!phaseConfig) {
  return [{
    json: {
      error: `Unknown phase: "${phaseKey}". Valid phases: ${PHASE_ORDER.join(', ')}.`
    }
  }];
}

const intentKey = (intent || '').toUpperCase();
const isAllowed = phaseConfig.allowed.includes(intentKey);

if (!isAllowed) {
  const currentIndex = PHASE_ORDER.indexOf(phaseKey);
  return [{
    json: {
      error: `Phase gate not cleared. Intent "${intentKey}" is not allowed in phase "${phaseKey}". User must confirm YES before advancing.`,
      allowedActions: phaseConfig.allowed,
      currentPhase: phaseKey,
      phaseGateRequired: true,
      errorIfSkip: `Cannot skip phase gate. Phase order is strictly: ${PHASE_ORDER.join(' → ')}. No skipping under any condition.`
    }
  }];
}

// Gate intents that require explicit YES confirmation
const gateIntents = ['USER_CONFIRMATION_YES', 'PROCESS_CLOSEOUT'];

return [{
  json: {
    allowedActions: phaseConfig.allowed,
    nextStepLabel: phaseConfig.nextStep,
    currentPhase: phaseKey,
    phaseGateRequired: gateIntents.includes(intentKey),
    description: phaseConfig.description,
    isAllowed: true
  }
}];

// Monday.com Tool
// ONLY call after explicit YES from user
// Actions: updateStatus, addComment, setDueDate, searchItem

const BOARD_ID = '18398486903';
const MONDAY_API_URL = 'https://api.monday.com/v2';

let input;
try {
  input = typeof $input.first().json === 'string'
    ? JSON.parse($input.first().json)
    : $input.first().json;
} catch (e) {
  return [{ json: { error: 'Invalid JSON input to monday_tool' } }];
}

const { action, studyUnitId, statusValue, comment, dueDate, assignee, itemId } = input;

// NOTE: Replace 'YOUR_MONDAY_API_KEY' with actual key from n8n credential
// In production, set this via n8n credential: "Monday.com API"
const apiKey = $env.MONDAY_API_KEY || 'CONFIGURE_VIA_N8N_CREDENTIAL';

const headers = {
  'Content-Type': 'application/json',
  'Authorization': apiKey
};

let query = '';
let variables = {};

if (action === 'searchItem') {
  // Search by Study Unit ID column first
  query = `query ($boardId: ID!) {
    boards(ids: [$boardId]) {
      items_page(limit: 50) {
        items {
          id
          name
          column_values(ids: ["text"]) {
            id
            text
          }
        }
      }
    }
  }`;
  variables = { boardId: BOARD_ID };

} else if (action === 'updateStatus') {
  if (!itemId || !statusValue) {
    return [{ json: { error: 'updateStatus requires itemId and statusValue' } }];
  }
  query = `mutation ($boardId: ID!, $itemId: ID!, $value: JSON!) {
    change_column_value(
      board_id: $boardId,
      item_id: $itemId,
      column_id: "status",
      value: $value
    ) {
      id
    }
  }`;
  variables = {
    boardId: BOARD_ID,
    itemId: itemId,
    value: JSON.stringify({ label: statusValue })
  };

} else if (action === 'addComment') {
  if (!itemId || !comment) {
    return [{ json: { error: 'addComment requires itemId and comment' } }];
  }
  query = `mutation ($itemId: ID!, $body: String!) {
    create_update(item_id: $itemId, body: $body) {
      id
      body
    }
  }`;
  variables = { itemId, body: comment };

} else if (action === 'setDueDate') {
  if (!itemId || !dueDate) {
    return [{ json: { error: 'setDueDate requires itemId and dueDate (YYYY-MM-DD)' } }];
  }
  query = `mutation ($boardId: ID!, $itemId: ID!, $value: JSON!) {
    change_column_value(
      board_id: $boardId,
      item_id: $itemId,
      column_id: "date4",
      value: $value
    ) {
      id
    }
  }`;
  variables = {
    boardId: BOARD_ID,
    itemId: itemId,
    value: JSON.stringify({ date: dueDate })
  };

} else {
  return [{ json: { error: `Unknown action: "${action}". Supported: updateStatus, addComment, setDueDate, searchItem` } }];
}

try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: MONDAY_API_URL,
    headers: headers,
    body: JSON.stringify({ query, variables }),
    returnFullResponse: false
  });

  if (response.errors) {
    return [{ json: { error: 'Monday.com API error', details: response.errors } }];
  }

  return [{ json: { success: true, action, data: response.data } }];
} catch (err) {
  return [{ json: { error: 'Monday.com request failed', message: err.message } }];
}

// Dropbox Tool
// ONLY call after explicit YES from user
// Actions: uploadFile, createFolder

const DROPBOX_API_BASE = 'https://content.dropboxapi.com/2';
const DROPBOX_API = 'https://api.dropboxapi.com/2';

let input;
try {
  input = typeof $input.first().json === 'string'
    ? JSON.parse($input.first().json)
    : $input.first().json;
} catch (e) {
  return [{ json: { error: 'Invalid JSON input to dropbox_tool' } }];
}

const {
  action,
  filePath,
  fileName,
  fileContent,
  contentType,
  certificationProgram,
  studyUnitId
} = input;

// NOTE: OAuth2 token must be configured via n8n "Dropbox OAuth2" credential
// In production this is handled by n8n's credential system
const accessToken = $env.DROPBOX_ACCESS_TOKEN || 'CONFIGURE_VIA_N8N_CREDENTIAL';

const authHeader = `Bearer ${accessToken}`;

if (action === 'createFolder') {
  const folderPath = filePath ||
    `/HOCK/${certificationProgram}/${studyUnitId}/${contentType}`;

  try {
    const response = await $helpers.httpRequest({
      method: 'POST',
      url: `${DROPBOX_API}/files/create_folder_v2`,
      headers: {
        'Authorization': authHeader,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        path: folderPath,
        autorename: false
      }),
      returnFullResponse: false
    });

    return [{ json: { success: true, action: 'createFolder', path: folderPath, data: response } }];
  } catch (err) {
    // 409 = folder already exists, not a real error
    if (err.message && err.message.includes('path/conflict')) {
      return [{ json: { success: true, action: 'createFolder', path: folderPath, note: 'Folder already exists' } }];
    }
    return [{ json: { error: 'Dropbox createFolder failed', message: err.message } }];
  }

} else if (action === 'uploadFile') {
  if (!fileName || !fileContent) {
    return [{ json: { error: 'uploadFile requires fileName and fileContent (base64)' } }];
  }

  const today = new Date().toISOString().split('T')[0];
  const fullPath = filePath ||
    `/HOCK/${certificationProgram}/${studyUnitId}/${contentType}/${studyUnitId}_${contentType}_${today}${getExtension(contentType)}`;

  const dropboxApiArg = JSON.stringify({
    path: fullPath,
    mode: 'overwrite',
    autorename: false,
    mute: false
  });

  // Decode base64 content
  const binaryContent = Buffer.from(fileContent, 'base64');

  try {
    const response = await $helpers.httpRequest({
      method: 'POST',
      url: `${DROPBOX_API_BASE}/files/upload`,
      headers: {
        'Authorization': authHeader,
        'Dropbox-API-Arg': dropboxApiArg,
        'Content-Type': 'application/octet-stream'
      },
      body: binaryContent,
      returnFullResponse: false
    });

    return [{
      json: {
        success: true,
        action: 'uploadFile',
        path: fullPath,
        fileName: fileName,
        data: response
      }
    }];
  } catch (err) {
    return [{ json: { error: 'Dropbox uploadFile failed', message: err.message } }];
  }

} else {
  return [{ json: { error: `Unknown action: "${action}". Supported: uploadFile, createFolder` } }];
}

function getExtension(type) {
  const map = {
    textbook: '.docx',
    mcqs: '.xlsx',
    slides: '.pdf',
    script: '.docx',
    flashcards: '.pdf'
  };
  return map[type] || '.file';
}

// Gamma Tool — Phase 3 ONLY
// ONLY call after explicit YES from user
// Action: createPresentation

const GAMMA_API_BASE = 'https://api.gamma.app/v1';
const HOCK_THEME_ID = '0mk4i94ypgimwxi';
const HOCK_THEME_URL = 'https://gamma.app/themes/share/0mk4i94ypgimwxi';

let input;
try {
  input = typeof $input.first().json === 'string'
    ? JSON.parse($input.first().json)
    : $input.first().json;
} catch (e) {
  return [{ json: { error: 'Invalid JSON input to gamma_tool' } }];
}

const { action, title, outlineContent, theme } = input;

// NOTE: API key must be configured via n8n "Gamma API" credential
const apiKey = $env.GAMMA_API_KEY || 'CONFIGURE_VIA_N8N_CREDENTIAL';

if (action !== 'createPresentation') {
  return [{ json: { error: `Unknown action: "${action}". Supported: createPresentation` } }];
}

if (!title || !outlineContent) {
  return [{ json: { error: 'createPresentation requires title and outlineContent' } }];
}

try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: `${GAMMA_API_BASE}/generate`,
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      title: title,
      markdown: outlineContent,
      theme: HOCK_THEME_ID,
      mode: 'document'
    }),
    returnFullResponse: false
  });

  const presentationId = response.id || response.presentationId || null;
  const presentationUrl = response.url || response.shareUrl ||
    (presentationId ? `https://gamma.app/docs/${presentationId}` : null);

  return [{
    json: {
      success: true,
      action: 'createPresentation',
      presentationId: presentationId,
      presentationUrl: presentationUrl,
      themeApplied: theme || 'Hock International',
      themeUrl: HOCK_THEME_URL,
      data: response
    }
  }];
} catch (err) {
  return [{
    json: {
      error: 'Gamma API request failed',
      message: err.message,
      note: 'Ensure Gamma API credential is configured in n8n and API access is enabled'
    }
  }];
}

