// Error Handler
// Catches failures from tool nodes and formats a user-friendly response

const errorData = $input.first().json;
const errorMessage = errorData.error?.message ||
  errorData.message ||
  errorData.error ||
  'An unexpected error occurred';

const timestamp = new Date().toISOString();

// Format user-friendly error message
const userMessage = `I encountered an error while processing your request.

**Error:** ${errorMessage}

Would you like me to retry this action, or would you prefer to continue without it?

Please reply:
- **YES** to retry the failed action
- **NO** to skip and continue
- **STOP** to halt the workflow`;

return [{
  json: {
    errorOccurred: true,
    userMessage: userMessage,
    rawError: errorMessage,
    timestamp: timestamp,
    retryAvailable: true
  }
}];
